async function api(number,suffix){
 const id=fixture.reviews[String(number)].review_id;
 // Use the same browser transport as the workspace. Keep its bearer in-page;
 // out-of-band APIRequestContext error logs can otherwise include auth headers.
 const result=await page.evaluate(async url=>{
  const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),30000);
  try {
   const token=document.querySelector('meta[name="csb-local-session"]').content;
   const response=await fetch(url,{headers:{Authorization:`Bearer ${token}`,Accept:'application/json'},cache:'no-store',signal:controller.signal});
   return {status:response.status,value:response.ok?await response.json():null};
  }catch(error){return {status:0,error_name:error.name};}finally{clearTimeout(timer);}
 },`${origin}/v1/reviews/${id}/${suffix}`);
 assert.equal(result.status,200,`Fixture ${suffix.split('?')[0]} browser HTTP status${result.error_name?` (${result.error_name})`:''}`);return result.value;
}
